type union MyUnion {
     integer ch1,
     integer ch2
  }
  template MyUnion m_myUnion := { ch1 := 5 }
  template MyUnion mw_myUnion := { ch1 := ? }
  var boolean v_checkResult := isvalue(m_myUnion);   // yields true
  v_checkResult := isvalue(mw_myUnion);   // yields false
  v_checkResult := isvalue(mw_myUnion.ch1); // yields false
  // note, this is different from ischosen(mw_myUnion.ch1) as isvalue checks the content of the 
  // choice ch1, while ischosen is checking if ch1 has been selected or not
  v_checkResult := isvalue(mw_myUnion.ch2); // yields false

type record MyRecord {
     MyUnion u optional 
  }
  template MyRecord m_myRecord := { u := m_myUnion }
  template MyRecord mw_myRecord := { u := mw_myUnion }
  template MyRecord m_myRecord2 := { u := omit }
  var boolean v_checkResult := isvalue(m_myRecord.u.ch1); // yields true
  v_checkResult := isvalue(mw_myRecord.u.ch1); // yields false
  v_checkResult := isvalue(mw_myRecord.u.ch2); // yields false
  v_checkResult := isvalue(m_myRecord.u.ch2); // yields false

type record MyRec {
     integer f1 optional,
     integer f2 optional
  }
  var MyRec v_myRec;
  var template MyRec v_myRecT;
  var boolean_checkResult := isvalue(v_myRec);   // yields false
  v_checkResult := isvalue(v_myRecT);  // yields false
  v_myRec  := { f1 := 5, f2 := omit }
  v_myRecT := { f1 := ?, f2 := 5 }
  v_checkResult := isvalue(v_myRec);   // yields true
  v_checkResult := isvalue(v_myRec.f2); // yields false; 
  v_checkResult := isvalue(v_myRecT);  // yields false
  v_checkResult := isvalue(v_myRecT.f1); // yields false
  v_checkResult := isvalue(v_myRecT.f2); // yields true
  v_myRecT.f2 := omit;
  v_checkResult := isvalue(v_myRecT.f2); // yields false

type record MyRec {
     integer f1,
     MyRec f2 optional
  }
  var MyRec v_myRec;
  var boolean_checkResult := isbound(v_myRec); // yields false
  v_myRec.f2 := omit;
  checkResult := isbound(v_myRec);      // yields true as v_myRec is partially initialized,
                  // field f2 is set to omit
  v_myRec := { f1 := 5, f2 := omit }
  checkResult := isbound(v_myRec);      // yields true as v_myRec is completely initialized
  checkResult := isbound(v_myRec.f2.f1);   // yields false as v_myRec.f2.f1 is inaccessible
  checkResult := isbound(v_myRec.f1/0);   // shall cause an error already during evaluating the
                  // operand because the operand is not a reference and division by 
                  // zero causes a runtime error
  type union MyUnion {
     integer ch1,
     MyRec  ch2
  }
  var template MyUnion v_myUnion;
  checkResult := isbound(v_myUnion);    // yields false, as v_myUnion is uninitialized
  checkResult := isbound(v_myUnion.ch1);  // yields false, as alternative ch1 is uninitialized
  v_myUnion := { ch1 := 5 };
  checkResult := isbound(v_myUnion);    // yields true
  checkResult := isbound(v_myUnion.ch1);  // yields true
  checkResult := isbound(v_myUnion.ch2);  // yields false as the ch2 alternative is not selected
  checkResult := isbound(v_myUnion.ch2.f1); // yields false as the field f1 is inaccessible
  checkResult := isbound(v_myUnion.ch1/0); // shall cause an error already during evaluating the
